/* ghostcn: Pricing Table Styles */
.gh-pricing {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 16px;
    line-height: 1.5;
    isolation: isolate;
    max-width: 64em;
    margin: 2em auto;
    padding: 2em 1em;
}

.gh-pricing *,
.gh-pricing *::before,
.gh-pricing *::after {
    box-sizing: border-box;
}

.gh-pricing-title {
    font-size: 1.875em;
    font-weight: 800;
    letter-spacing: -0.025em;
    text-align: center;
    color: var(--foreground, #09090b);
    margin-bottom: 0.75em;
}

.gh-pricing-desc {
    text-align: center;
    color: var(--muted-foreground, #71717a);
    margin-bottom: 2.5em;
}

.gh-pricing-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2em;
}

@media (min-width: 768px) {
    .gh-pricing-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.gh-pricing-card {
    border: 1px solid var(--border, #e4e4e7);
    border-radius: min(var(--radius, 0.5em), 1.5em);
    padding: 1.5em;
    background-color: var(--card, #ffffff);
    color: var(--card-foreground, #09090b);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    position: relative;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
    transition: box-shadow 0.2s ease;
}

.gh-pricing-card:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.gh-pricing-card-featured {
    border: 2px solid var(--primary, var(--ghost-accent-color, #18181b));
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.gh-pricing-badge {
    position: absolute;
    top: -0.75em;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--primary, var(--ghost-accent-color, #18181b));
    color: var(--primary-foreground, #ffffff);
    font-size: 0.75em;
    font-weight: 600;
    padding: 0.25em 0.75em;
    border-radius: 9999px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.gh-pricing-btn {
    display: block;
    width: 100%;
    text-align: center;
    padding: 0.625em 1em;
    border-radius: var(--radius, 0.5em);
    font-size: 0.875em;
    font-weight: 500;
    text-decoration: none;
    border: 1px solid var(--input, #e4e4e7);
    color: var(--foreground, #09090b);
    background-color: var(--background, #ffffff);
    margin-top: 1.5em;
    transition: background-color 0.15s ease;
}

.gh-pricing-btn:hover {
    background-color: var(--muted, #f4f4f5);
}

.gh-pricing-btn-primary {
    background-color: var(--primary, var(--ghost-accent-color, #18181b));
    border-color: var(--primary, var(--ghost-accent-color, #18181b));
    color: var(--primary-foreground, #ffffff);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-pricing-btn-primary:hover {
    opacity: 0.9;
}
